if(regions.isEmpty()||fixed.isEmpty())throw new IllegalStateException("Expected water/foil groups");for(Motion m:s.get(MotionManager.class).getObjects())if(m instanceof RotatingMotion){String a=((RotationAngle)((RotatingMotion)m).getRotationSpecification()).getRotationAngle().getDefinition();if(!a.equals("<0 deg>")&&!a.equals("0.0"))throw new IllegalStateException("Static smoke requires zero angle: "+a);}
((UserFieldFunction)s.getFieldFunctionManager().getFunction("HYDRO_HydrostaticGauge")).setDefinition("<1000 kg/m^3>*<9.8100004196167 m/s^2>*(<2 m> - $$Position[2])");
