long cells=((FvRepresentation)s.getRepresentationManager().getObject("Volume Mesh")).getCellCount();
Dimensions pd=new Dimensions();pd.setPressure(1);UserFieldFunction pe=field("HYDRO_PressureIdentityError_"+runId,"abs($AbsolutePressure - $Pressure - <101325 Pa> - $HYDRO_HydrostaticGauge)",pd);MaxReport check=s.getReportManager().createReport(MaxReport.class);check.setFieldFunction(pe);check.getParts().setObjects(regions);double peError=check.getReportMonitorValue();if(!(peError<.05))throw new IllegalStateException("Absolute pressure identity failed: "+peError);
