MaxReport zmax=s.getReportManager().createReport(MaxReport.class);zmax.setFieldFunction(s.getFieldFunctionManager().getFunction("Position").getComponentFunction(2));List<Boundary> walls=new ArrayList<>(fixed);walls.addAll(flap);zmax.getParts().setObjects(walls);
