XyzInternalTable pt=s.getTableManager().createTable(XyzInternalTable.class);pt.getParts().setObjects(walls);pt.setExtractVertexData(false);pt.setFieldFunctions(List.of(s.getFieldFunctionManager().getFunction("AbsolutePressure"),s.getFieldFunctionManager().getFunction("Pressure"),s.getFieldFunctionManager().getFunction("WallYplus")));pt.extract();pt.export(out.resolve("foil_pressure.csv").toString());
